<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create a personal account · CareSys</title><link rel="stylesheet" href="/assets/caresys.css"></head><body><main class="auth-shell"><section class="auth-story"><div class="brand"><span class="brand-mark">✚</span>CareSys</div><div><h1>Your career starts with you.</h1><p>Create a personal account before joining an agency. You choose when recruiters can find you and what career history they can see.</p></div><footer>CareSys Agent · Personal account</footer></section><section class="auth-form"><h1>Create your account</h1><p class="sub">Use one personal account across all agencies. Your email and account name remain reserved if you cancel a subscription or disable your account. Sign in to recover an existing account.</p><?php foreach((array)session('errors') as $error): ?><div class="alert error" role="alert"><?= esc($error) ?></div><?php endforeach ?><?php if(session('error')): ?><div class="alert error" role="alert"><?= esc(session('error')) ?></div><?php endif ?><form method="post" action="<?= url_to('register') ?>"><?= csrf_field() ?><div class="field"><label for="username">Account name</label><input id="username" name="username" autocomplete="username" value="<?= esc(old('username'),'attr') ?>" required></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" value="<?= esc(old('email'),'attr') ?>" required></div><div class="field"><label for="password">Create a password</label><input id="password" name="password" type="password" autocomplete="new-password" required></div><div class="field"><label for="password_confirm">Repeat your password</label><input id="password_confirm" name="password_confirm" type="password" autocomplete="new-password" required></div><button type="submit">Create personal account</button></form><p>Already registered? <a href="/login">Sign in</a></p></section></main><?= view('components/form_help') ?><script src="/assets/form-controls.js" defer></script><script src="/assets/caresys.js" defer></script></body></html>
